import React, { useState } from 'react';
import { Send, FileText, Sparkles } from 'lucide-react';

export function ChatInterface() {
  const [messages, setMessages] = useState([
    {
      id: 1,
      role: 'system',
      content: 'أهلاً بك في المساعد القانوني. كيف يمكنني مساعدتك اليوم في صياغة أو مراجعة المستندات؟'
    }
  ]);
  const [input, setInput] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;
    
    // Add user message
    setMessages(prev => [...prev, { id: Date.now(), role: 'user', content: input }]);
    setInput('');
    
    // Placeholder for AI response
    setTimeout(() => {
      setMessages(prev => [...prev, { 
        id: Date.now(), 
        role: 'system', 
        content: 'جاري تحليل طلبك والبحث في المبادئ القضائية العمانية...' 
      }]);
    }, 1000);
  };

  return (
    <div className="flex flex-col h-full bg-gray-50/50">
      <div className="px-6 py-4 border-b border-slate-200 flex items-center gap-3">
        <Sparkles className="w-5 h-5 text-blue-600" />
        <h2 className="font-semibold text-navy-900 text-lg">المساعد الذكي</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex flex-col max-w-[90%] ${msg.role === 'user' ? 'mr-auto items-end' : 'ml-auto items-start'}`}
          >
            <div 
              className={`p-4 rounded-2xl leading-relaxed ${
                msg.role === 'user' 
                  ? 'bg-blue-600 text-white rounded-tr-none' 
                  : 'bg-white border border-slate-200 text-gray-800 rounded-tl-none shadow-sm'
              }`}
            >
              {msg.content}
            </div>
            <span className="text-xs text-slate-500 mt-2 px-2">
              {msg.role === 'user' ? 'المحامي' : 'المساعد القانوني'}
            </span>
          </div>
        ))}
      </div>

      <div className="p-4 bg-white border-t border-slate-200">
        <form 
          onSubmit={handleSubmit}
          className="relative flex items-center bg-gray-50 border border-slate-200 rounded-xl overflow-hidden focus-within:ring-2 focus-within:ring-blue-600/20 focus-within:border-blue-600 transition-all"
        >
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="اسأل المساعد أو اطلب صياغة مستند..."
            className="w-full bg-transparent border-none px-4 py-4 outline-none text-gray-800 placeholder-slate-500"
            dir="rtl"
          />
          <button 
            type="submit"
            disabled={!input.trim()}
            className="absolute left-2 p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:hover:bg-blue-600 transition-colors"
          >
            <Send className="w-4 h-4 rtl:-scale-x-100" />
          </button>
        </form>
        <div className="text-center mt-2">
          <p className="text-xs text-slate-500">
            يستخدم النظام التوليد المعزز بالاسترجاع لضمان دقة المعلومات
          </p>
        </div>
      </div>
    </div>
  );
}
